const express = require('express');
const { WorkOrder, Asset } = require('../models');
const { verifySession } = require('../auth');

const app = express();
app.use(express.json());

WorkOrder.addHook('beforeUpdate', async (order) => {
  if (order.changed('assetId')) {
    const asset = await Asset.findByPk(order.assetId);
    if (asset) {
      asset.status = 'UNDER_REPAIR';
      await asset.save();
    }
  }
});

app.put('/api/work-orders/:id', verifySession, async (req, res) => {
  const { id } = req.params;
  const { assetId, description } = req.body;

  const order = await WorkOrder.findOne({ where: { id, createdBy: req.user.id } });
  if (!order) {
    return res.status(404).json({ error: 'Work order not found' });
  }

  // Validate that the new assetId belongs to the user's authorized facility
  if (assetId) {
    const targetAsset = await Asset.findOne({
      where: { id: assetId, facilityId: req.user.facilityId }
    });
    if (!targetAsset) {
      return res.status(403).json({ error: 'Access denied: specified asset does not belong to your facility' });
    }
  }

  order.assetId = assetId;
  order.description = description;
  await order.save();

  res.json({ success: true, order });
});

app.listen(8107);
